edits.before:
#overlay #hubMain.hub-classes .class-dossier-grid .class-dossier .class-dossier-art {
  position: relative;
  inset: auto;
  z-index: 0;
  aspect-ratio: 16 / 9;
  background: #ffffff;
  border-bottom: 1px solid rgba(202,203,204,.22);
}

#overlay #hubMain.hub-classes .class-dossier-grid .class-dossier .class-dossier-art img {
  display: block;
  position: absolute;
  inset: 0;
  object-fit: contain;
  object-position: center;
  filter: none;
  transform: none;
  transition: none;
  -webkit-mask-image: none;
  mask-image: none;
}

#overlay #hubMain.hub-classes .class-dossier-grid .class-dossier .class-dossier-copy {
  position: relative;
  inset: auto;
  padding: 18px 18px 16px;
  background: #141617;
}

#overlay #hubMain.hub-classes .class-dossier-grid .class-dossier .class-dossier-index {
  z-index: 1;
  padding: 5px 7px;
  background: #141617;
  border: 1px solid rgba(202,203,204,.3);
}

.route-options { display: flex; gap: 8px; overflow-x: auto; padding: 6px 2px; scrollbar-width: thin;
  -webkit-mask-image: linear-gradient(90deg, transparent 0, #000000 16px, #000000 calc(100% - 16px), transparent 100%);
  mask-image: linear-gradient(90deg, transparent 0, #000000 16px, #000000 calc(100% - 16px), transparent 100%); }

.route-option {
  --route-accent: #c0c3c6;
  min-width: 145px; flex: 1 0 145px; display: flex; gap: 10px; align-items: center; padding: 9px 11px;
  text-align: left; background: #2a2d30; border: 1px solid #757a7e80; border-left: 2px solid var(--route-accent);
  color: var(--exp-text); border-radius: var(--radius-panel); box-shadow: none;
}

.coll-slot.off { width: 82px; height: 114px; display: flex; align-items: center; justify-content: center;
    border: 1px dashed #3a3a3a; border-radius: var(--radius-panel);
    background: repeating-linear-gradient(45deg, #191919, #191919 6px, #141414 6px, #141414 12px); }

#overlay #hubMain.hub-ach .collection-command {
  border-color: rgba(188,193,196,.18); border-left-color: var(--gold-main);
  background: linear-gradient(110deg, rgba(27,29,31,.96), rgba(16,17,18,.96));
}

#overlay #hubMain.hub-ach .coll-room .base-bar {
  background: rgba(11,12,13,.92);
  border: 1px solid rgba(230,203,118,.24);
  box-shadow: inset 0 1px 2px rgba(0,0,0,.5);
}

#overlay #hubMain.hub-ach .coll-room .base-bar i {
  position: relative; overflow: hidden;
  background: linear-gradient(90deg, #8a7442, var(--gold-main) 55%, #f1dd9b);
  box-shadow: 0 0 8px rgba(230,203,118,.3);
}

#overlay #hubMain.hub-ach .coll-room .base-bar i::after {
  content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 40%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(235,233,227,.34), transparent);
  transform: translateX(-120%);
  animation: achSweep 3.8s ease-in-out infinite;
}

#overlay #hubMain.hub-ach .coll-ms {
  position: relative; overflow: hidden;
  border-color: rgba(170,174,177,.14); border-radius:0;
  background: linear-gradient(180deg, rgba(18,19,20,.66), rgba(13,14,15,.72));
  transition: border-color var(--ach-fast), background var(--ach-fast), box-shadow var(--ach-fast);
}

#overlay #hubMain.hub-ach .coll-ms.done {
  border-color: rgba(230,203,118,.28);
  background: linear-gradient(180deg, rgba(38,33,22,.42), rgba(17,18,20,.74));
}

#overlay #hubMain.hub-ach .coll-ms.reach {
  border-color: rgba(230,203,118,.62);
  background: linear-gradient(90deg, rgba(230,203,118,.12), rgba(230,203,118,.028) 46%, rgba(16,18,19,.6));
  box-shadow: inset 2px 0 0 var(--gold-main), 0 0 16px rgba(230,203,118,.12);
}

#overlay #hubMain.hub-ach .coll-ms.reach::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  box-shadow: 0 0 22px rgba(230,203,118,.16), inset 0 0 26px rgba(230,203,118,.05);
  animation: achSummon 2.6s ease-in-out infinite alternate;
}

#overlay #hubMain.hub-ach .coll-ms.reach:hover {
  border-color: rgba(230,203,118,.8);
  box-shadow: inset 2px 0 0 var(--gold-main), 0 0 20px rgba(230,203,118,.18);
}

#overlay #hubMain.hub-ach .coll-group-head b::before {
  content: ''; display: inline-block; width: 12px; height: 1px; margin-right: 8px;
  vertical-align: .32em;
  background: linear-gradient(90deg, transparent, #e6cb76a8);
  box-shadow: 0 0 4px #e6cb7655;
}

#overlay #hubMain.hub-ach .coll-room .coll-group {
  margin-top: 18px; padding: 14px 16px 18px;
  border: 1px solid rgba(170,174,177,.18); border-left: 3px solid var(--role-accent, #e6cb76);
  background: linear-gradient(180deg, rgba(25,27,29,.88), rgba(16,18,19,.9));
}

#overlay #hubMain.hub-ach .coll-room .coll-group-head {
  display: grid; grid-template-columns: minmax(110px, auto) minmax(0, 1fr) auto;
  align-items: center; gap: 16px; margin: 0 0 12px; padding-bottom: 11px;
  border-bottom: 1px solid rgba(170,174,177,.2);
}

#overlay #hubMain.hub-ach .coll-slot.on {
  transition: transform var(--ach-lift), border-color var(--ach-lift), box-shadow var(--ach-lift);
}

#overlay #hubMain.hub-ach .back-card {
  transition: border-color var(--ach-lift), transform var(--ach-lift),
    box-shadow var(--ach-lift), background var(--ach-lift);
}

#overlay #hubMain.hub-ach .back-card.on {
  border-color: var(--gold-main);
  box-shadow: inset 0 0 0 1px rgba(230,203,118,.25), 0 0 16px rgba(230,203,118,.18);
}

#overlay #hubMain.hub-ach .collection-panel .back-grid {
    width: 100%; max-width: 1000px; margin-inline: auto;
    justify-content: center; gap: 18px;
  }

#overlay #hubMain.hub-ach .collection-command .story-strip {
  display: flex; align-items: baseline; gap: 10px;
  margin-top: 10px; padding-top: 9px;
  border-top: 1px solid rgba(170,174,177,.14);
  font-size: 12px; line-height: 1.7; color: #9a9fa2;
}

#overlay #hubMain.hub-ach .collection-command .story-strip .ss-tag {
  flex: none; display: inline-flex; align-items: center; gap: 5px;
  color: var(--gold-main); letter-spacing: 1px;
  padding-right: 12px;
  background: linear-gradient(270deg, transparent, rgba(230,203,118,.4)) right center / 10px 1px no-repeat;
}

#sidebar .route-title {
  display: inline-flex; align-items: center; gap: 8px;
  color: #f4e2a5; font-size: 12.5px; letter-spacing: .24em;
  text-shadow: 0 0 10px rgba(230,203,118,.18);
}

#sidebar .route-title::before {
  content: ''; display: block; width: 16px; height: 1px;
  background: linear-gradient(90deg, transparent, #e6cb76b3);
  box-shadow: 0 0 4px #e6cb7655;
}

#sidebar .route-option {
  background: linear-gradient(180deg, rgba(34,36,39,.88), rgba(24,26,27,.92));
  border-color: rgba(170,174,177,.26);
  transition: transform var(--exh-lift), border-color var(--exh-fast),
    background var(--exh-fast), box-shadow var(--exh-fast);
}

#sidebar .route-option::after {
  content: ''; position: absolute; top: 0; left: 12%; right: 12%; height: 1px;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, #e6cb76b8, transparent);
  opacity: 0;
  transition: opacity var(--exh-fast);
}

#sidebar .route-option:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: rgba(230,203,118,.58);
  background: linear-gradient(180deg, rgba(45,48,52,.95), rgba(30,33,35,.95));
  box-shadow: 0 6px 14px rgba(7,7,8,.38), 0 0 10px rgba(230,203,118,.1);
}

#sidebar .route-option:active:not(:disabled) {
  transform: translateY(0) scale(.97);
  transition: transform var(--exh-press), border-color var(--exh-press),
    background var(--exh-press), box-shadow var(--exh-press);
}

#sidebar .route-option.selected {
  border-color: #e6cb76;
  background: linear-gradient(180deg, rgba(50,53,57,.95), rgba(34,37,40,.95));
  box-shadow: 0 0 12px rgba(230,203,118,.12);
}

#sidebar .route-option:focus-visible,
#topBtns button:focus-visible,
#logPanel .log-toggle:focus-visible {
  outline: 1px solid #e6cb76cc;
  outline-offset: 2px;
  box-shadow: 0 0 0 1px #101112, 0 0 12px rgba(230,203,118,.35);
}

#overlay .card.chest .loot-manifest > div:first-child > b {
  color: #f1f1f1; letter-spacing: 3px;
  text-shadow: 0 2px 8px rgba(7,7,8,.6);
}

#overlay .card.chest .loot-capacity b {
  color: #f4e2a5; font-variant-numeric: tabular-nums; letter-spacing: .02em;
  text-shadow: 0 0 10px rgba(230,203,118,.22);
}

#overlay .card.chest .chest-reveal::after {
  content: ''; position: absolute; left: 50%; bottom: 0; z-index: -1;
  width: min(380px, 60%); height: 46%; transform: translateX(-50%);
  pointer-events: none;
  background: radial-gradient(ellipse 52% 42% at 50% 62%, rgba(230,203,118,.22), rgba(230,203,118,.05) 58%, transparent 76%);
  animation: rbhPoolBreath 4.5s ease-in-out infinite alternate;
}

#overlay .card.chest .chest-ops .ov-btn {
  transition: color var(--rbh-fast), border-color var(--rbh-fast), background var(--rbh-fast),
    box-shadow var(--rbh-fast), transform var(--rbh-fast), filter var(--rbh-fast);
}

#overlay .card.chest .chest-ops .ov-btn:not(.ok):hover {
  border-color: rgba(230,203,118,.55);
  background: rgba(27,29,31,.85);
  color: #f4f4f4;
  box-shadow: 0 0 12px rgba(230,203,118,.12);
  transform: translateY(-1px);
}

#overlay .card.chest .chest-ops .ov-btn.ok {
  border-color: #f1dd9b;
  background: linear-gradient(180deg, #dfdcd5, #e6cb76 58%, #d7ba5c);
  color: #241c09;
  box-shadow: inset 0 1px 0 rgba(241,239,234,.55), 0 4px 16px rgba(7,7,8,.4), 0 0 18px rgba(230,203,118,.28);
  letter-spacing: 3px;
}

#overlay .card.chest .chest-ops .ov-btn.ok:hover {
  filter: brightness(1.07);
  box-shadow: inset 0 1px 0 rgba(244,243,239,.65), 0 6px 18px rgba(7,7,8,.45), 0 0 24px rgba(230,203,118,.4);
  transform: translateY(-1px);
}

#overlay .card.chest .chest-ops .ov-btn:active {
  transform: translateY(1px) scale(.97);
  filter: brightness(1.1);
  transition-duration: var(--rbh-press);
}

#overlay .card:has(.expedition-manual) > h2 {
  color: #f4f4f4; letter-spacing: 6px;
  text-shadow: 0 0 16px rgba(230,203,118,.14), 0 2px 6px rgba(6,6,7,.6);
}

#overlay .card:has(.expedition-manual) .manual-step {
  border-color: rgba(170,174,177,.2);
  background: linear-gradient(180deg, rgba(26,28,30,.72), rgba(20,22,23,.8));
  transition: border-color var(--rbh-fast), box-shadow var(--rbh-fast), background var(--rbh-fast);
}

#overlay .card:has(.expedition-manual) .manual-step::before {
  content: ''; position: absolute; top: 0; left: 12%; right: 12%; height: 1px;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, #e6cb76cc, transparent);
  opacity: .12;
  transition: opacity var(--rbh-fast);
}

#overlay .card:has(.expedition-manual) .manual-step:hover {
  border-color: rgba(230,203,118,.5);
  background: linear-gradient(180deg, rgba(32,34,37,.78), rgba(23,25,26,.84));
  box-shadow: 0 8px 20px rgba(7,7,8,.35), 0 0 10px rgba(230,203,118,.08);
}

#overlay .card:has(.expedition-manual) .manual-control-key {
  background: linear-gradient(180deg, #1e2123, #17181a);
  border-color: rgba(170,174,177,.4);
  border-bottom-color: rgba(230,203,118,.5);
  color: #e5e6e6; letter-spacing: 1px;
}

#overlay .card:has(.expedition-manual) .ov-btn.back-sm {
  transition: color var(--rbh-fast), border-color var(--rbh-fast), background var(--rbh-fast),
    box-shadow var(--rbh-fast), transform var(--rbh-fast);
}

#overlay .card:has(.expedition-manual) .ov-btn.back-sm:hover {
  color: #e1dfd9; border-color: rgba(230,203,118,.6);
  background: rgba(21,23,24,.85);
  box-shadow: 0 0 10px rgba(230,203,118,.14);
  transform: translateY(-1px);
}

.back-card { width: 106px; display: flex; flex-direction: column; align-items: center; gap: 6px;
    padding: 12px 8px 10px; border-radius:0; border: 1.5px solid #343434; color: inherit;
    background: #1d1d1d; cursor: pointer; transition: all .15s; font-family: inherit; }

.back-card.locked .back-thumb::after { content: 'LOCK'; position: absolute; inset: 0; z-index: 5;
    display: flex; align-items: center; justify-content: center; font-size: 19px;
    background: rgba(7,7,7,.5); border-radius:0; }

.chest-reveal::before { content:''; position:absolute; left:50%; bottom:6%; transform:translateX(-50%);
    width:72%; height:58%; border-radius:50%; pointer-events:none; z-index:-1;
    background:radial-gradient(ellipse at center, rgba(255,224,120,.42), rgba(255,224,120,0) 70%);
    filter:blur(6px); animation: chestGlowPulse 1.9s ease-in-out .55s infinite backwards; }

.shop-price { display: inline-flex; align-items: center; gap: 6px; padding: 6px 16px;
    font-family: var(--cal); font-size: 15px; font-weight: 700; letter-spacing: 1px; color: #33270a;
    background: linear-gradient(180deg, #ffe387, #eec43c); border: 1px solid #e1dfd7; border-radius: 999px;
    box-shadow: 0 4px 12px rgba(11,12,13,.45), inset 0 1px 0 rgba(255,255,255,.55);
    cursor: pointer; transition: transform .13s ease, filter .13s ease; }
